-- Completes the normalized core model; no business-critical villa or workflow data is stored as an opaque JSON document.
create table public.employee_roles (employee_id uuid not null references public.employees(id), role_id uuid not null references public.roles(id), organization_id uuid not null references public.organizations(id), assigned_at timestamptz not null default now(), assigned_by uuid references auth.users(id), primary key(employee_id,role_id));
create table public.villa_specifications (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), villa_id uuid not null references public.villas(id), category text not null, specification_key text not null, specification_value text not null, unit text, source_document_id uuid references public.villa_documents(id), unique(villa_id,category,specification_key));
create table public.villa_features (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), villa_id uuid not null references public.villas(id), name text not null, description text, status text not null default 'PLANNED', unique(villa_id,name));
create table public.work_subcategories (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), category_id uuid not null references public.work_categories(id), name text not null, active boolean not null default true, unique(category_id,name));
create table public.delay_attributions (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), delay_event_id uuid not null references public.delay_events(id), attributed_party_type text not null check(attributed_party_type in ('INTERNAL_TEAM','EMPLOYEE','VENDOR','SUPPLIER','CLIENT','DESIGN','WEATHER','OTHER')), employee_id uuid references public.employees(id), vendor_id uuid references public.vendors(id), supplier_id uuid references public.suppliers(id), contribution_minutes integer not null check(contribution_minutes >= 0), explanation text, evidence_attachment_id uuid references public.attachments(id), created_at timestamptz not null default now(), created_by uuid references auth.users(id));

do $$ declare t text; begin foreach t in array array['employee_roles','villa_specifications','villa_features','work_subcategories','delay_attributions'] loop execute format('alter table public.%I enable row level security', t); execute format('create policy %I on public.%I for all using (public.is_org_member(organization_id)) with check (public.is_org_member(organization_id))', t || '_tenant_access', t); end loop; end $$;
create index delay_attributions_event_idx on public.delay_attributions(delay_event_id);
create index villa_specifications_villa_idx on public.villa_specifications(villa_id,category);
